	wire i_lw = op[5] & ~op[3];		
	wire i_sw = op[5] & op[3];		
	wire i_beq = op[2] & ~op[1];	
	wire i_lui = op[3] & op[2];		


	assign RegDst 		= i_Rt;

	assign RegWrite 	= i_Rt | i_lw | i_lui;

	assign ALUSrc 		= i_lw | i_sw | i_lui;
	assign MemWrite		= i_sw;
	assign MemRead		= i_lw;

	assign MemtoReg		= i_lw;
	assign Branch		= i_beq;

	assign ALUctr[1] = i_Rt | i_lui;
	assign ALUctr[0] = i_beq | i_lui;
endmodule

