description:
Implement the Verilog module based on the following description.
Build a 4-bit binary counter with an enable signal and synchronous active high reset signal.
// (1) reset: Resets the counter to 4'b0000.
// (2) enable: Enables counting when high.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    input enable,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset,
    input enable,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else if (enable) begin
            // Increment the counter if enable is high
            q <= q + 1;
        end
    end

endmodule

