module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter H=2'b00, I=2'b01, J=2'b10, K=2'b11;

    always_comb begin
		case (state)
			H: next_state = in ? J : I;
			I: next_state = in ? K : J;
			J: next_state = in ? H : K;
			K: next_state = in ? I : H;
		endcase
    end

    always_comb begin
		case (state)
			H: out = 0;
			I: out = 1;
			J: out = 0;
			K: out = 1;
		endcase
    end

endmodule

