description:
Design a circuit that toggles an 8-bit LED output between two states based on a clock input. The LED output will change states every 12 million clock cycles, where it switches from a value of 1 to a value of 2 and back again, creating a blinking effect at a controlled frequency determined by the clock signal. This module effectively implements a simple LED blink pattern generator utilizing a counter to track clock cycles.
module top_module(
   input clk,
   output [7:0] LED
   );

code:
module top_module(
   input clk,
   output [7:0] LED
   );parameter TOGGLE_CLOCK = 32'd12000000;

   reg [31:0]   counter = 32'd0;
   reg [7:0]    led_state = 8'd0;

   assign LED = led_state;

   always @(posedge clk)
     begin
        if (counter == TOGGLE_CLOCK)
          begin
             counter <= 32'd0;
             if (led_state == 8'd1)
               begin
                  led_state <= 8'd2;
               end
             else
               begin
                  led_state <= 8'd1;
               end
          end
        else
          begin
             counter <= counter + 1'd1;
          end
     end 

endmodule

