module freq_divider(
	input clk_in,
	input rst_n,
	output reg clk_out
);

	reg [2:0] cnt;

	always @(posedge clk_in or negedge rst_n) begin
		if (!rst_n) begin
			cnt <= 3'b0;
			clk_out <= 1'b0;
		end
		else if (cnt == 3'b111) begin
			cnt <= 3'b0;
			clk_out <= ~clk_out;
		end
		else begin
			cnt <= cnt + 1'b1;
		end
	end

endmodule

