module garage_door_opener (
    input clk,
    input resetn,
    input open,
    input close,
    output reg door_open,
    output reg door_closed);

    parameter CLOSED = 0, OPENING = 1, OPEN = 2, CLOSING = 3;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (~resetn) state <= CLOSED;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            CLOSED: next_state = open ? OPENING : CLOSED;
            OPENING: next_state = OPEN;
            OPEN: next_state = close ? CLOSING : OPEN;
            CLOSING: next_state = CLOSED;
            default: next_state = CLOSED;
        endcase
    end

    always @(state) begin
        case (state)
            CLOSED: begin
                door_open = 0;
                door_closed = 1;
            end
            OPEN: begin
                door_open = 1;
                door_closed = 0;
            end
            default: begin
                door_open = 0;
                door_closed = 0;
            end
        endcase
    end
endmodule

