module top_module(
    input [3:0] A,
    input [3:0] B,
    input areset,
    input clk,        // Added the clk input
    output [3:0] S,
    output C
);reg [3:0] sum_reg;
reg carry_reg;

always @(posedge clk or negedge areset) begin
    if (!areset) begin  // Changed to '!areset' for reset condition
        sum_reg <= 4'b0;
        carry_reg <= 1'b0;
    end else begin
        {carry_reg, sum_reg} <= A + B + carry_reg; // Updated to handle carry properly
    end
end

assign S = sum_reg;
assign C = carry_reg;

endmodule

