description:
Design a clock-driven circuit that generates a blinking output signal. This module takes in a clock input and a reset signal, allowing it to toggle the output `blink_o` at a specified frequency determined by the `FREQUENCY` and `SECONDS` parameters. The output will flip its state once per second, based on the clock cycles counted up to a calculated division factor. When the reset signal is asserted, the counter resets, and the blinking output is initialized to LOW.
module top_module(
   input  wire clk_i,
   input  wire rst_i,
   output wire blink_o
);

code:
module top_module(
   input  wire clk_i,
   input  wire rst_i,
   output wire blink_o
);parameter [31:0] FREQUENCY=25E6;
parameter [31:0] SECONDS=1;

parameter DIV = FREQUENCY * SECONDS;
reg blink;
reg [$clog2(DIV)-1:0] cnt = 0;

always @(posedge clk_i) begin : P1
   if (rst_i == 1'b1) begin
      cnt = 0;
      blink <= 1'b0;
   end else begin
      if (cnt == DIV) begin
         cnt = 0;
         blink <=  ~((blink));
      end else begin
        cnt = cnt + 1;
      end
   end
end

assign blink_o = blink;

endmodule

